const regions={
  asahidake:{label:'Asahidake',center:[142.854,43.663],zoom:11.0,bearing:12,pitch:54},
  rusutsu:{label:'Rusutsu',center:[140.88,42.74],zoom:11.0,bearing:-18,pitch:54},
  furano:{label:'Furano',center:[142.355,43.325],zoom:11.0,bearing:16,pitch:54},
  niseko:{label:'Niseko',center:[140.69,42.86],zoom:10.5,bearing:-20,pitch:54},
  kamui:{label:'Kamui Ski Links',center:[142.19,43.70],zoom:11.0,bearing:8,pitch:54},
  kiroro:{label:'Kiroro',center:[140.99,43.07],zoom:10.8,bearing:-12,pitch:54}
};
const state={points:[],drawing:false,mapStyle:'satellite',saved:JSON.parse(localStorage.getItem('powderline.routes')||'[]')};
const $=s=>document.querySelector(s);
const gsiAttribution='<a href="https://maps.gsi.go.jp/development/ichiran.html" target="_blank" rel="noopener">GSI Japan</a>';
const terrainAttribution='<a href="https://registry.opendata.aws/terrain-tiles/" target="_blank" rel="noopener">AWS Open Data Terrain Tiles</a>';
const skiAttribution='<a href="https://www.openskidata.org/" target="_blank" rel="noopener">OpenSkiData / OpenSkiMap.org</a> · © OpenStreetMap contributors (ODbL)';
const emptyCollection={type:'FeatureCollection',features:[]};
const mapStyle={version:8,sources:{
  'gsi-satellite':{type:'raster',tiles:['https://cyberjapandata.gsi.go.jp/xyz/seamlessphoto/{z}/{x}/{y}.jpg'],tileSize:256,maxzoom:18,attribution:gsiAttribution},
  'gsi-topo':{type:'raster',tiles:['https://cyberjapandata.gsi.go.jp/xyz/std/{z}/{x}/{y}.png'],tileSize:256,maxzoom:18,attribution:gsiAttribution}
},layers:[
  {id:'gsi-satellite',type:'raster',source:'gsi-satellite'},
  {id:'gsi-topo',type:'raster',source:'gsi-topo',layout:{visibility:'none'}}
]};
const map=new maplibregl.Map({container:'map',style:mapStyle,center:regions.furano.center,zoom:regions.furano.zoom,bearing:regions.furano.bearing,pitch:regions.furano.pitch,antialias:true,maxPitch:75});
map.addControl(new maplibregl.NavigationControl({showCompass:true}), 'bottom-right');
function setTerrain(){map.addSource('terrain',{type:'raster-dem',tiles:['https://s3.amazonaws.com/elevation-tiles-prod/terrarium/{z}/{x}/{y}.png'],tileSize:256,maxzoom:15,encoding:'terrarium',attribution:terrainAttribution});map.setTerrain({source:'terrain',exaggeration:1.25});map.addLayer({id:'terrain-hillshade',type:'hillshade',source:'terrain',layout:{visibility:'none'},paint:{'hillshade-exaggeration':0.25,'hillshade-shadow-color':'#33423c','hillshade-highlight-color':'#f7f5e9'}})}
function addSkiLayers(){map.addSource('ski-facilities',{type:'geojson',data:emptyCollection,attribution:skiAttribution});map.addLayer({id:'ski-runs',type:'line',source:'ski-facilities',filter:['==',['get','powderlineType'],'run'],paint:{'line-color':['match',['get','difficulty'],'novice','#54b948','easy','#54b948','intermediate','#2788d3','advanced','#e74b3c','expert','#202725','freeride','#b14bd1','#2788d3'],'line-width':['interpolate',['linear'],['zoom'],9,1.5,14,4],'line-opacity':.88}});map.addLayer({id:'ski-lifts',type:'line',source:'ski-facilities',filter:['==',['get','powderlineType'],'lift'],paint:{'line-color':'#ff9d2e','line-width':['interpolate',['linear'],['zoom'],9,2,14,5],'line-opacity':.95}});map.addLayer({id:'ski-stations',type:'circle',source:'ski-facilities',filter:['==',['get','powderlineType'],'station'],paint:{'circle-radius':['interpolate',['linear'],['zoom'],9,3,14,7],'circle-color':['match',['get','position'],'top','#f05b42','bottom','#28a9db','#f7f4e8'],'circle-stroke-color':'#14211f','circle-stroke-width':1.5}})}
map.on('load',()=>{setTerrain();addSkiLayers();map.addSource('route',{type:'geojson',data:emptyCollection});map.addLayer({id:'route-glow',type:'line',source:'route',paint:{'line-color':'#14211f','line-width':7,'line-opacity':.28,'line-blur':2}});map.addLayer({id:'route-line',type:'line',source:'route',paint:{'line-color':'#d8ff43','line-width':4,'line-opacity':1}});map.addSource('route-points',{type:'geojson',data:emptyCollection});map.addLayer({id:'route-points',type:'circle',source:'route-points',paint:{'circle-radius':5,'circle-color':'#d8ff43','circle-stroke-color':'#14211f','circle-stroke-width':2}});loadSkiData('furano');render();});
map.on('sourcedata',e=>{if(e.sourceId==='terrain'&&e.isSourceLoaded)$('#mapStatus').textContent='3D terrain ready'});
map.on('error',e=>{if(e.sourceId==='terrain')$('#mapStatus').textContent='Terrain data unavailable'});
function setMapStyle(style){state.mapStyle=style;const topo=style==='topo';if(map.getLayer('gsi-satellite'))map.setLayoutProperty('gsi-satellite','visibility',topo?'none':'visible');if(map.getLayer('gsi-topo'))map.setLayoutProperty('gsi-topo','visibility',topo?'visible':'none');if(map.getLayer('terrain-hillshade'))map.setLayoutProperty('terrain-hillshade','visibility',topo?'visible':'none');$('#satelliteBtn').classList.toggle('active',!topo);$('#topoBtn').classList.toggle('active',topo);$('#satelliteBtn').setAttribute('aria-pressed',String(!topo));$('#topoBtn').setAttribute('aria-pressed',String(topo));toast(topo?'Topo / contours map':'Satellite map')}
let skiLoadToken=0;
async function loadSkiData(region){const token=++skiLoadToken;$('#facilityStatus').textContent='Loading ski facilities…';try{const response=await fetch(new URL(`./data/ski/${region}.geojson`,document.baseURI));if(!response.ok)throw new Error(String(response.status));const data=await response.json();if(token!==skiLoadToken)return;map.getSource('ski-facilities').setData(data);const c=data.metadata?.counts||{};$('#facilityStatus').textContent=data.metadata?.status==='available'?`${c.lifts||0} lifts · ${c.runs||0} runs · ${c.stations||0} stations`:'데이터 미확보'}catch(error){if(token!==skiLoadToken)return;map.getSource('ski-facilities').setData(emptyCollection);$('#facilityStatus').textContent='데이터 미확보';console.warn('Ski facility data unavailable',error)}}
function setLayerVisibility(ids,visible){ids.forEach(id=>{if(map.getLayer(id))map.setLayoutProperty(id,'visibility',visible?'visible':'none')})}
function escapeHtml(value){return String(value??'').replace(/[&<>"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[char]))}
map.on('click','ski-lifts',event=>{const p=event.features?.[0]?.properties;if(!p)return;new maplibregl.Popup().setLngLat(event.lngLat).setHTML(`<div class="ski-popup"><strong>${escapeHtml(p.name||'Unnamed lift')}</strong><span>${escapeHtml(p.liftType||'type unavailable')}</span></div>`).addTo(map)});map.on('mouseenter','ski-lifts',()=>map.getCanvas().style.cursor='pointer');map.on('mouseleave','ski-lifts',()=>map.getCanvas().style.cursor='');
function feature(){return {type:'Feature',geometry:{type:'LineString',coordinates:state.points.map(p=>[p.lng,p.lat])},properties:{}}}
function render(){if(!map.getSource('route'))return;map.getSource('route').setData(state.points.length>1?{type:'FeatureCollection',features:[feature()]}:{type:'FeatureCollection',features:[]});map.getSource('route-points').setData({type:'FeatureCollection',features:state.points.map((p,i)=>({type:'Feature',geometry:{type:'Point',coordinates:[p.lng,p.lat]},properties:{i}}))});$('#points').textContent=state.points.length;$('#distance').textContent=distanceKm(state.points).toFixed(1)+' km';$('#descent').textContent='—'}
function distanceKm(ps){let d=0;for(let i=1;i<ps.length;i++){const a=ps[i-1],b=ps[i],r=Math.PI/180, x=(b.lng-a.lng)*r*Math.cos((a.lat+b.lat)*r/2),y=(b.lat-a.lat)*r;d+=6371*Math.sqrt(x*x+y*y)}return d}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2500)}
function setRegion(){const region=$('#region').value,r=regions[region];map.flyTo({center:r.center,zoom:r.zoom,bearing:r.bearing,pitch:r.pitch,duration:1400});loadSkiData(region);clearLine();toast('View moved to '+r.label)}
function clearLine(){state.points=[];state.drawing=false;$('#drawBtn').textContent='＋ Draw line';render()}
$('#region').addEventListener('change',setRegion);$('#clearBtn').addEventListener('click',clearLine);$('#drawBtn').addEventListener('click',()=>{state.drawing=!state.drawing;$('#drawBtn').textContent=state.drawing?'Finish line':'＋ Draw line';toast(state.drawing?'Click across the mountain to draw':'Line saved in canvas')});
map.on('click',e=>{if(!state.drawing)return;state.points.push({lng:e.lngLat.lng,lat:e.lngLat.lat});render()});map.on('dblclick',e=>{if(state.drawing){state.drawing=false;$('#drawBtn').textContent='＋ Draw line';toast('Line finished — drag vertices to refine it')}});
map.on('mousedown','route-points',e=>{if(!state.points.length)return;e.preventDefault();const i=e.features[0].properties.i;map.getCanvas().style.cursor='grabbing';map.on('mousemove',move);map.once('mouseup',up);function move(ev){state.points[i]={lng:ev.lngLat.lng,lat:ev.lngLat.lat};render()}function up(){map.getCanvas().style.cursor='';map.off('mousemove',move)}});
function gpxString(){const now=new Date().toISOString();return `<?xml version="1.0" encoding="UTF-8"?><gpx version="1.1" creator="Powderline"><metadata><name>Powderline route</name><time>${now}</time></metadata><trk><name>Powderline line</name><trkseg>${state.points.map(p=>`<trkpt lat="${p.lat}" lon="${p.lng}"></trkpt>`).join('')}</trkseg></trk></gpx>`}
$('#exportBtn').addEventListener('click',()=>{if(state.points.length<2)return toast('Draw a line first');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([gpxString()],{type:'application/gpx+xml'}));a.download='powderline-route.gpx';a.click();toast('GPX exported')});
$('#gpxInput').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;const xml=new DOMParser().parseFromString(await f.text(),'application/xml');state.points=[...xml.querySelectorAll('trkpt,rtept')].map(n=>({lat:+n.getAttribute('lat'),lng:+n.getAttribute('lon')}));render();if(state.points.length){const bounds=state.points.reduce((b,p)=>b.extend([p.lng,p.lat]),new maplibregl.LngLatBounds([state.points[0].lng,state.points[0].lat],[state.points[0].lng,state.points[0].lat]));map.fitBounds(bounds,{padding:90,duration:900,maxZoom:13})}toast(`${state.points.length} GPX points loaded`)});
function renderSaved(){const el=$('#savedList');$('#savedCount').textContent=state.saved.length;if(!state.saved.length){el.innerHTML='<p class="empty">No saved lines yet.</p>';return}el.innerHTML=state.saved.map((r,i)=>`<button class="saved-item" data-i="${i}"><span>${r.name}</span><small>${r.km.toFixed(1)} km</small></button>`).join('');el.querySelectorAll('.saved-item').forEach(b=>b.addEventListener('click',()=>{state.points=state.saved[+b.dataset.i].points;render();toast('Saved line loaded')}))}
$('#saveBtn').addEventListener('click',()=>{if(state.points.length<2)return toast('Draw a line first');const r=regions[$('#region').value];state.saved.unshift({name:r.label+' line '+new Date().toLocaleDateString('en-CA'),km:distanceKm(state.points),points:state.points});localStorage.setItem('powderline.routes',JSON.stringify(state.saved));renderSaved();toast('Route saved locally')});
$('#liftsToggle').addEventListener('change',e=>setLayerVisibility(['ski-lifts','ski-stations'],e.target.checked));$('#runsToggle').addEventListener('change',e=>setLayerVisibility(['ski-runs'],e.target.checked));$('#gpxToggle').addEventListener('change',e=>setLayerVisibility(['route-glow','route-line','route-points'],e.target.checked));$('#satelliteBtn').addEventListener('click',()=>setMapStyle('satellite'));$('#topoBtn').addEventListener('click',()=>setMapStyle('topo'));$('#tiltBtn').addEventListener('click',()=>map.easeTo({pitch:map.getPitch()>20?15:58,duration:700}));$('#resetBtn').addEventListener('click',()=>setRegion());renderSaved();
